svg.script:
test(() => {
  const line = document.getElementById("self");
  assert_true(line.isPointInStroke({x: 50, y: 20.4}));
  assert_false(line.isPointInStroke({x: 50, y: 20.6}));
}, "A CSS transform on the shape changes the local stroke width");

test(() => {
  const line = document.getElementById("parent");
  assert_true(line.isPointInStroke({x: 50, y: 40.2}));
  assert_false(line.isPointInStroke({x: 50, y: 40.4}));
}, "A CSS transform on an ancestor changes the local stroke width");

test(() => {
  const line = document.getElementById("nonuniform");
  assert_true(line.isPointInStroke({x: 50, y: 60.2}));
  assert_false(line.isPointInStroke({x: 50, y: 60.3}));
}, "Nonuniform CSS scaling uses the perpendicular scale");

test(() => {
  const line = document.getElementById("override");
  assert_true(line.isPointInStroke({x: 50, y: 80.4}));
  assert_false(line.isPointInStroke({x: 50, y: 80.6}));
}, "A CSS transform overrides the transform presentation attribute");

test(() => {
  const line = document.getElementById("skew");
  assert_true(line.isPointInStroke({x: 50, y: 101.2}));
  assert_false(line.isPointInStroke({x: 50, y: 101.5}));
}, "A CSS skew changes distance to the stroke in local coordinates");

test(() => {
  const line = document.getElementById("dynamic");
  assert_true(line.isPointInStroke({x: 50, y: 120.6}));
  line.style.transform = "scale(2)";
  assert_false(line.isPointInStroke({x: 50, y: 120.6}));
}, "Changing a CSS transform updates stroke hit testing");
